import flax.linen as nn
import jax.numpy as jnp
from jax import random
from typing import Dict, Any

def _define_hyperparameters():
    """Define hyperparameters for the CNN model."""
    return {
        'learning_rate': 0.001,
        'num_filters': 128,  # Number of filters in the convolutional layer
        'kernel_size': 7,    # Width of the convolutional kernel
        'dropout_rate': 0.2
    }

class RNA_CNN(nn.Module):
    """A 1D CNN for RNA sequence modeling."""
    d_output: int
    task_type: str
    num_filters: int
    kernel_size: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Input shape: (batch, seq_len, 4)

        # 1. Convolutional layer to learn motifs
        x = nn.Conv(features=self.num_filters, kernel_size=(self.kernel_size,))(x)
        x = nn.relu(x)

        # 2. Global average pooling over the sequence dimension
        x = jnp.mean(x, axis=1)  # Shape: (batch, num_filters)

        # 3. Dropout and final dense layer for prediction
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        x = nn.Dense(features=self.d_output)(x)

        # 4. Squeeze output for single-output regression tasks
        if self.task_type == "regression":
            return x.squeeze(axis=-1)
        else:
            return x

class CNNNetwork:
    """Wrapper for the RNA_CNN model to match the required interface."""
    def __init__(self, **kwargs):
        self.network = RNA_CNN(**kwargs)

    def init(self, rng_key, dummy_input):
        """Initialize network parameters."""
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        """Apply the network's forward pass."""
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    """Factory function to create the CNN model."""
    return CNNNetwork(
        d_output=hparams['d_output'],
        task_type=hparams['task_type'],
        num_filters=hparams['num_filters'],
        kernel_size=hparams['kernel_size'],
        dropout_rate=hparams['dropout_rate']
    )
